async def act(page):
    import re
    import asyncio

    # Navigate to the Manage Products grid (relative path) from current page
    await page.goto('/index.php/admin/catalog/product/')
    await page.wait_for_load_state('networkidle')
    # allow dynamic widgets to render
    await asyncio.sleep(1)

    found_brands = []

    # Try to locate accessible tables and parse them for a Qty column and Brand/Manufacturer column
    tables = page.get_by_role('table')
    table_count = await tables.count()

    for i in range(table_count):
        table = tables.nth(i)
        try:
            table_text = await table.inner_text()
        except Exception:
            continue

        # Normalize NBSPs and split into non-empty lines
        table_text = table_text.replace('\u00A0', ' ')
        lines = [ln.strip() for ln in table_text.splitlines() if ln.strip()]
        if not lines:
            continue

        header = lines[0]
        cols = re.split(r'\t|\s{2,}', header)

        qty_idx = None
        brand_idx = None
        name_idx = None
        sku_idx = None
        for idx, c in enumerate(cols):
            lc = c.strip().lower()
            if qty_idx is None and any(k in lc for k in ('qty', 'quantity', 'stock')):
                qty_idx = idx
            if brand_idx is None and any(k in lc for k in ('brand', 'manufacturer', 'vendor')):
                brand_idx = idx
            if name_idx is None and any(k in lc for k in ('name', 'product')):
                name_idx = idx
            if sku_idx is None and 'sku' in lc:
                sku_idx = idx

        if qty_idx is None:
            continue

        for row in lines[1:]:
            cells = re.split(r'\t|\s{2,}', row)
            if len(cells) <= qty_idx:
                continue
            qty_cell = cells[qty_idx].strip()
            m = re.search(r'(-?\d+)', qty_cell)
            if not m:
                continue
            try:
                qty_val = int(m.group(1))
            except Exception:
                continue

            if qty_val == 3:
                brand_text = ''
                if brand_idx is not None and len(cells) > brand_idx:
                    brand_text = cells[brand_idx].strip()
                elif name_idx is not None and len(cells) > name_idx:
                    brand_text = cells[name_idx].strip()
                elif sku_idx is not None and len(cells) > sku_idx:
                    brand_text = cells[sku_idx].strip()

                if brand_text and brand_text not in found_brands:
                    found_brands.append(brand_text)

    # Print each found brand (one per line) and return the list
    for b in found_brands:
        print(b)
    return found_brands

